//! Internal build capabilities carried in the existing node attributes map.
//! This deliberately does not append fields to the bincode handshake. Missing,
//! malformed and unknown advertisements never grant a capability. The reserved
//! namespace is generated by the process, not configurable through node.attr.*.
//!
//! Lifecycle activation deliberately requires every member to preserve the
//! state, including data-only nodes: an old JSON decoder could accept and
//! discard the field. The pre-advertisement baseline is master since PR #78
//! (e07faf4c; ffe4b591 and 64ea4834 are such builds): its IndexMetadata
//! already carries `#[serde(default)] lifecycle` and its mirror fills it, so a
//! node that makes no reserved `rustic.internal.*` claim at all is treated as
//! lifecycle-preserving.
//! A node that does make claims must advertise lifecycle support under a
//! recognized schema (and prove it, see capability_probe); malformed, partial
//! or future-schema advertisements fail closed, and such joiners/candidates and
//! their publications are refused once lifecycle state exists. It does not
//! establish a general minimum-node-version policy.
//!
//! Segment formats: `segment_read_max` is this build's read maximum and
//! `segment_write` the format it writes at startup (the committed cluster
//! floor it last applied, `gateway::load_committed_segment_format`, capped by
//! `RUSTIC_SEGMENT_WRITE_VERSION`). The live
//! write version follows the cluster's segment format floor
//! (`elasticsearch_cluster::compatibility`), which the master raises once
//! every member reads more and which only rises, so the startup value is a
//! lower bound of what the node writes and every member reads the floor.
//! Members below the floor are refused (`require_member`).
use elasticsearch_cluster::state::{ClusterState, DiscoveryNode};
use std::collections::BTreeMap;

const PREFIX: &str = "rustic.internal.";
const SCHEMA: &str = "rustic.internal.capabilities_schema";
const SEGMENT_READ_MAX: &str = "rustic.internal.segment_read_max";
const SEGMENT_WRITE: &str = "rustic.internal.segment_write";

#[derive(Clone, Copy, Debug)]
pub(crate) enum Capability {
    MappingUuidV2,
    ScrollTouch,
    LifecycleState,
    PublishedVersionHeader,
    CapacityV1,
    CapacityDomainV1,
    CapacityPressureV1,
    QtfPinnedV1,
    /// Query-phase answers carry the adaptive replica selection stats header.
    AdaptiveStatsV1,
    /// A primary with a `Snapshot` recovery source is restored by adopting
    /// the snapshot's shard files (`snapshot_api::file_restore`); an older
    /// build would open it empty. Checked by the master (file restore or
    /// re-index) and by the `restore_in_progress` allocation decider.
    SnapshotFileRestoreV1,
    /// The node snapshots its own primaries into the repository
    /// (`snapshot::upload`, ES `SnapshotShardsService`). For a primary on a
    /// node without it the master pulls the frozen files (disk-guarded).
    SnapshotShardUploadV1,
}
impl Capability {
    fn key(self) -> &'static str {
        match self {
            Self::MappingUuidV2 => "rustic.internal.mapping_uuid_v2",
            Self::ScrollTouch => "rustic.internal.scroll_touch",
            Self::LifecycleState => "rustic.internal.lifecycle_state",
            Self::CapacityV1 => "rustic.internal.capacity_v1",
            Self::CapacityDomainV1 => "rustic.internal.capacity_domain_v1",
            Self::QtfPinnedV1 => "rustic.internal.qtf_pinned_v1",
            Self::AdaptiveStatsV1 => "rustic.internal.adaptive_stats_v1",
            Self::CapacityPressureV1 => "rustic.internal.capacity_pressure_v1",
            Self::PublishedVersionHeader => "rustic.internal.published_version_header",
            Self::SnapshotFileRestoreV1 => elasticsearch_cluster::allocation::SNAPSHOT_FILE_RESTORE_ATTR,
            Self::SnapshotShardUploadV1 => "rustic.internal.snapshot_shard_upload_v1",
        }
    }
}

/// Node startup refuses an invalid explicit writer setting. The setting caps
/// the negotiated write version (testing, emergencies); it never raises it
/// above the cluster's floor.
pub(crate) fn validate_writer_setting(value: Option<&str>) -> Result<(), String> {
    if let Some(value) = value {
        let version = value.parse::<u32>().map_err(|_| format!("invalid RUSTIC_SEGMENT_WRITE_VERSION [{value}]"))?;
        if !(elasticsearch_engine::rustic_core::codec::MIN_WRITE_VERSION..=elasticsearch_engine::rustic_core::codec::VERSION).contains(&version) {
            return Err(format!("unsupported RUSTIC_SEGMENT_WRITE_VERSION [{value}]"));
        }
    }
    Ok(())
}

/// `segment_write` is the write version at the time of the call (node
/// startup: the committed floor last applied, capped): a lower bound of what the node
/// writes later, since the floor only rises. Attributes are fixed for the
/// process (they are part of its capability proof), so the live value is
/// not re-advertised; joins are gated on `segment_read_max` and the floor.
pub(crate) fn advertise(attributes: &mut BTreeMap<String, String>) {
    attributes.retain(|key, _| !key.starts_with(PREFIX));
    attributes.insert(SCHEMA.into(), "1".into());
    attributes.insert(SEGMENT_READ_MAX.into(), elasticsearch_engine::rustic_core::codec::VERSION.to_string());
    attributes.insert(SEGMENT_WRITE.into(), elasticsearch_engine::rustic_core::codec::write_version().to_string());
    for cap in [Capability::MappingUuidV2, Capability::ScrollTouch, Capability::LifecycleState, Capability::PublishedVersionHeader, Capability::CapacityV1, Capability::CapacityDomainV1, Capability::CapacityPressureV1, Capability::QtfPinnedV1, Capability::AdaptiveStatsV1, Capability::SnapshotFileRestoreV1, Capability::SnapshotShardUploadV1] {
        attributes.insert(cap.key().into(), "1".into());
    }
}

pub(crate) fn supports(node: &DiscoveryNode, capability: Capability) -> bool {
    node.attributes.get(SCHEMA).is_some_and(|v| v == "1")
        && node.attributes.get(capability.key()).is_some_and(|v| v == "1")
}

/// Consult this process's advertisement, not its possibly stale accepted-state
/// entry after restart. An explicit v12 writer must not acknowledge new writes
/// while any existing data member can only read v11. A write no newer than
/// the cluster's segment format floor is gated on the floor rather than on
/// per-peer proofs (`capability_probe::require_writer_proofs`).
pub(crate) fn require_local_writer(state: &ClusterState, local: &DiscoveryNode) -> Result<(), String> {
    let (_, write) = elasticsearch_cluster::compatibility::segment_formats(local)?;
    for peer in state.data_nodes().filter(|peer| peer.id != local.id) {
        elasticsearch_cluster::compatibility::require_segment_reader(peer, write)?;
    }
    crate::capability_probe::require_writer_proofs(state, local)
}

pub(crate) fn has_lifecycle(state: &ClusterState) -> bool {
    state.metadata.indices.values().any(|index| index.lifecycle.is_some())
}

/// No reserved claim at all: the pre-advertisement baseline (see module doc).
pub(crate) fn pre_advertisement(node: &DiscoveryNode) -> bool {
    !node.attributes.keys().any(|key| key.starts_with(PREFIX))
}

/// The baseline already round-trips `IndexMetadata.lifecycle`; an advertising
/// build must say so explicitly under a schema this build recognizes.
pub(crate) fn preserves_lifecycle(node: &DiscoveryNode) -> bool {
    pre_advertisement(node) || supports(node, Capability::LifecycleState)
}

pub(crate) fn require_lifecycle_reader(node: &DiscoveryNode) -> Result<(), String> {
    if preserves_lifecycle(node) { Ok(()) } else {
        Err(format!("node [{}] does not advertise lifecycle-state preservation; upgrade it before enabling lifecycle state or joining this cluster", node.name))
    }
}

/// An admitted pressure relocation whose target copy has not started: its
/// recovery must run under a capacity-pressure-capable owner and master. Once
/// the copy starts, its `capacity-` allocation id is only an opaque id (the
/// cooldown timestamp an old master ignores), so the latch clears.
pub(crate) fn pending_pressure_allocation(state: &ClusterState) -> bool {
    state.routing_table.all_shards().any(|copy| copy.state == elasticsearch_cluster::state::ShardState::Initializing
        && copy.allocation_id().is_some_and(|id| id.starts_with("capacity-")))
}

/// Whether `node` may be a member of `state` (join, pre-vote, election, or a
/// recipient of a publication). Checking this before a join is admitted keeps
/// a leader from publishing a membership its followers must refuse, which
/// would fail the quorum and make it step down on every retry.
pub(crate) fn require_member(state: &ClusterState, node: &DiscoveryNode) -> Result<(), String> {
    if pending_pressure_allocation(state) && !supports(node, Capability::CapacityPressureV1) {
        return Err(format!("node [{}] does not advertise capacity-pressure support; an admitted pressure relocation is in progress", node.name));
    }
    if has_lifecycle(state) { require_lifecycle_reader(node)?; }
    elasticsearch_cluster::compatibility::require_segment_floor(state, node)
}

/// An old receiver can accept JSON while silently dropping unknown index
/// metadata. Gate all recipients, not just the current master's decoder.
pub(crate) fn validate_lifecycle_members(state: &ClusterState) -> Result<(), String> {
    for node in state.nodes.values() { require_member(state, node)?; }
    Ok(())
}

/// Also fence an older leader that would publish a state which omits lifecycle
/// metadata already accepted here. A capable leader may legitimately remove it.
pub(crate) fn validate_lifecycle_publication(old: &ClusterState, next: &ClusterState) -> Result<(), String> {
    // The floor is never lowered either, but against a committed floor:
    // `old` is a follower's last accepted state here (coord applies
    // `validate_committed_segment_floor` / `validate_segment_floor_publication`).
    elasticsearch_cluster::compatibility::validate_segment_members(next)?;
    if pending_pressure_allocation(old)
        && !next.master().is_some_and(|master|supports(master,Capability::CapacityPressureV1)) {
        return Err("pressure allocation state cannot be published by an older master".into());
    }
    if has_lifecycle(old) || has_lifecycle(next) {
        require_lifecycle_reader(next.master().ok_or_else(|| "lifecycle publication has no master".to_string())?)?;
    }
    validate_lifecycle_members(next)
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;

    fn node(attributes: BTreeMap<String, String>) -> DiscoveryNode {
        DiscoveryNode { id: "n".into(), name: "n".into(), ephemeral_id: "e".into(),
            transport_address: "127.0.0.1:9300".into(), http_address: "127.0.0.1:9200".into(),
            host: "localhost".into(), ip: "127.0.0.1".into(), roles: Default::default(),
            attributes, version: "9.5.5".into() }
    }

    #[test]
    fn legacy_and_malformed_advertisements_never_enable_features() {
        let mut peer = node(Default::default());
        assert!(!supports(&peer, Capability::MappingUuidV2));
        peer.attributes.insert(Capability::MappingUuidV2.key().into(), "1".into());
        assert!(!supports(&peer, Capability::MappingUuidV2), "schema must be recognized");
        peer.attributes.insert(SCHEMA.into(), "1".into());
        assert!(supports(&peer, Capability::MappingUuidV2));
        for invalid in ["true", "01", "2", "", " 1"] {
            peer.attributes.insert(Capability::MappingUuidV2.key().into(), invalid.into());
            assert!(!supports(&peer, Capability::MappingUuidV2), "{invalid}");
        }
        peer.attributes.insert(Capability::MappingUuidV2.key().into(), "1".into());
        peer.attributes.insert(SCHEMA.into(), "2".into());
        assert!(!supports(&peer, Capability::MappingUuidV2), "future schemas fail closed");
    }

    #[test]
    fn process_overrides_reserved_attributes_without_changing_handshake_shape() {
        let mut attrs = BTreeMap::from([("zone".into(), "west".into()),
            (SEGMENT_READ_MAX.into(), "999".into()),
            ("rustic.internal.forged_feature".into(), "1".into())]);
        advertise(&mut attrs);
        assert_eq!(attrs["zone"], "west");
        assert_eq!(attrs[SEGMENT_READ_MAX], elasticsearch_engine::rustic_core::codec::VERSION.to_string());
        assert!(!attrs.contains_key("rustic.internal.forged_feature"));
        let local = node(attrs);
        let bytes = bincode::serialize(&local).unwrap();
        // The exact pre-advertisement DiscoveryNode struct can still decode:
        // capabilities are ordinary map entries, not trailing binary fields.
        #[derive(serde::Serialize, serde::Deserialize)]
        struct LegacyDiscoveryNode {
            id: String, name: String, ephemeral_id: String, transport_address: String,
            http_address: String, host: String, ip: String,
            roles: std::collections::BTreeSet<elasticsearch_cluster::state::Role>,
            attributes: BTreeMap<String, String>, version: String,
        }
        let old: LegacyDiscoveryNode = bincode::deserialize(&bytes).unwrap();
        assert_eq!(bincode::serialize(&old).unwrap(), bytes, "no new trailing fields may hide from an old receiver");
        let back: DiscoveryNode = bincode::deserialize(&bytes).unwrap();
        assert_eq!(back, local);
        assert!(supports(&back, Capability::MappingUuidV2));
    }
    pub(crate) fn lifecycle_state() -> ClusterState {
        let mut state = ClusterState::empty("c");
        let mut attributes = BTreeMap::new();
        advertise(&mut attributes);
        let local = node(attributes);
        state.master_node_id = Some(local.id.clone());
        state.nodes.insert(local.id.clone(), local);
        let index = serde_json::from_value(serde_json::json!({
            "name": "i", "uuid": "u-i", "version": 1, "mapping_version": 1,
            "settings_version": 1, "aliases_version": 1, "state": "open",
            "settings": {}, "mappings": {}, "aliases": {}, "number_of_shards": 1,
            "number_of_replicas": 0, "routing_num_shards": 1, "primary_terms": [1],
            "in_sync_allocation_ids": {}, "creation_date": 0, "lifecycle": {"phase": "hot"}
        })).unwrap();
        state.metadata.indices.insert("i".into(), index);
        state
    }

    /// An advertising build that does not claim lifecycle support under a
    /// recognized schema (partial or future advertisement).
    fn unrecognized_advertiser(id: &str) -> DiscoveryNode {
        let mut attributes = BTreeMap::new();
        advertise(&mut attributes);
        attributes.insert(SCHEMA.into(), "2".into());
        let mut n = node(attributes);
        n.id = id.into();
        n
    }

    #[test]
    fn lifecycle_activation_rejects_an_unrecognized_advertiser() {
        let mut state = lifecycle_state();
        assert!(validate_lifecycle_members(&state).is_ok());
        let old = unrecognized_advertiser("old");
        state.nodes.insert(old.id.clone(), old);
        assert!(validate_lifecycle_members(&state).is_err());
        let mut before_activation = state.clone();
        before_activation.metadata.indices.get_mut("i").unwrap().lifecycle = None;
        assert!(validate_lifecycle_publication(&before_activation, &state).is_err(), "activation must reject an unrecognized member already present");
        state.metadata.indices.get_mut("i").unwrap().lifecycle = None;
        assert!(validate_lifecycle_members(&state).is_ok(), "ordinary mixed-version metadata remains allowed");
        // A partial advertisement (schema without the lifecycle key) fails closed.
        let mut partial = BTreeMap::new();
        partial.insert(SCHEMA.into(), "1".into());
        assert!(require_lifecycle_reader(&node(partial)).is_err());
    }

    /// Master ffe4b591/64ea4834 already persist `#[serde(default)] lifecycle`
    /// and advertise nothing: a rolling upgrade with ILM indices must work.
    #[test]
    fn pre_advertisement_baseline_preserves_lifecycle() {
        let mut state = lifecycle_state();
        let mut baseline = node(Default::default());
        baseline.id = "old".into();
        state.nodes.insert(baseline.id.clone(), baseline.clone());
        assert!(validate_lifecycle_members(&state).is_ok(), "an upgraded master must keep accepting baseline members");
        // The baseline master's publication of lifecycle state is accepted.
        let current = state.clone();
        let mut next = state.clone();
        next.master_node_id = Some("old".into());
        next.version += 1;
        assert!(validate_lifecycle_publication(&current, &next).is_ok());
        // ...including legitimately removing it (it implements ILM removal).
        next.metadata.indices.get_mut("i").unwrap().lifecycle = None;
        assert!(validate_lifecycle_publication(&current, &next).is_ok());
    }

    /// A state with one admitted pressure relocation of shard 0 of `i`.
    pub(crate) fn pressure_state(started: bool) -> ClusterState {
        use elasticsearch_cluster::state::{AllocationId, IndexRoutingTable, IndexShardRoutingTable, ShardRouting, ShardState};
        let mut state = lifecycle_state();
        state.metadata.indices.get_mut("i").unwrap().lifecycle = None;
        let copy = ShardRouting { index: "i".into(), shard: 0, primary: false,
            state: if started { ShardState::Started } else { ShardState::Initializing },
            node_id: Some("n".into()), relocating_node_id: None,
            allocation_id: Some(AllocationId { id: "capacity-1-abc".into(), relocation_id: None }),
            recovery_source: None, unassigned_info: None, expected_shard_size_in_bytes: None };
        let table = IndexRoutingTable { index_uuid: "u-i".into(), shards: vec![IndexShardRoutingTable { shard: 0, copies: vec![copy] }] };
        state.routing_table.indices.insert("i".into(), table);
        state
    }

    #[test]
    fn pressure_latch_refuses_old_members_only_until_the_relocated_copy_starts() {
        let baseline = node(Default::default());
        let pending = pressure_state(false);
        assert!(pending_pressure_allocation(&pending));
        assert!(require_member(&pending, &baseline).is_err(), "an old joiner is refused while the admitted move is pending");
        let mut capable = BTreeMap::new();
        advertise(&mut capable);
        assert!(require_member(&pending, &node(capable)).is_ok());
        let started = pressure_state(true);
        assert!(!pending_pressure_allocation(&started), "a started copy no longer latches the cluster");
        assert!(require_member(&started, &baseline).is_ok());
        let mut joined = started.clone();
        let mut old = baseline.clone();
        old.id = "old".into();
        joined.nodes.insert(old.id.clone(), old);
        assert!(validate_lifecycle_members(&joined).is_ok());
        let mut from_old_master = joined.clone();
        from_old_master.master_node_id = Some("old".into());
        assert!(validate_lifecycle_publication(&started, &from_old_master).is_ok(), "an old master may publish once the move completed");
        let mut pending_joined = pending.clone();
        pending_joined.master_node_id = Some("old".into());
        pending_joined.nodes.insert("old".into(), joined.nodes["old"].clone());
        assert!(validate_lifecycle_publication(&pending, &pending_joined).is_err());
    }

    #[test]
    fn old_leader_cannot_silently_erase_accepted_lifecycle_state() {
        let old = lifecycle_state();
        let mut next = old.clone();
        next.metadata.indices.get_mut("i").unwrap().lifecycle = None;
        assert!(validate_lifecycle_publication(&old, &next).is_ok(), "capable master can remove lifecycle state");
        let master = unrecognized_advertiser("n");
        next.nodes.insert("n".into(), master);
        assert!(validate_lifecycle_publication(&old, &next).is_err());
    }

    #[test]
    fn explicit_unsupported_writer_setting_is_not_silently_downgraded() {
        use elasticsearch_engine::rustic_core::codec::{MIN_WRITE_VERSION, VERSION};
        assert!(validate_writer_setting(None).is_ok());
        for v in MIN_WRITE_VERSION..=VERSION { assert!(validate_writer_setting(Some(&v.to_string())).is_ok(), "{v}"); }
        let (below, above) = ((MIN_WRITE_VERSION - 1).to_string(), (VERSION + 1).to_string());
        for invalid in ["", "garbage", below.as_str(), above.as_str(), " 12"] { assert!(validate_writer_setting(Some(invalid)).is_err(), "{invalid}"); }
    }

    fn floor_state(floor: u32) -> ClusterState {
        let mut state = ClusterState::empty("c");
        state.metadata.cluster_uuid = "u".into();
        let mut attributes = BTreeMap::new();
        advertise(&mut attributes);
        let local = node(attributes);
        state.master_node_id = Some(local.id.clone());
        state.nodes.insert(local.id.clone(), local);
        elasticsearch_cluster::compatibility::raise_segment_format(&mut state, floor);
        state
    }

    /// Once the floor rose past v11 a pre-advertisement (old) build can
    /// neither join, vote nor be published to; before, it still can.
    #[test]
    fn members_below_the_segment_floor_are_refused() {
        let mut old = node(Default::default());
        old.id = "old".into();
        let mixed = floor_state(11);
        assert!(require_member(&mixed, &old).is_ok(), "mixed clusters keep admitting old builds");
        let upgraded = floor_state(elasticsearch_engine::rustic_core::codec::VERSION);
        let err = require_member(&upgraded, &old).unwrap_err();
        assert!(err.contains("downgrading"), "{err}");
        let mut capable = BTreeMap::new();
        advertise(&mut capable);
        assert!(require_member(&upgraded, &node(capable)).is_ok());
        // A publication naming the old node is refused, and so is one that
        // would lower the floor.
        let mut next = upgraded.clone();
        next.nodes.insert(old.id.clone(), old);
        assert!(validate_lifecycle_publication(&upgraded, &next).is_err());
        let mut lowered = upgraded.clone();
        lowered.metadata.customs.remove(elasticsearch_cluster::compatibility::SEGMENT_FORMAT_CUSTOM);
        assert!(elasticsearch_cluster::compatibility::validate_segment_floor_publication(&upgraded, &lowered).is_err());
        assert!(validate_lifecycle_publication(&upgraded, &lowered).is_ok(), "an accepted (maybe uncommitted) floor is not binding");
        assert!(validate_lifecycle_publication(&mixed, &upgraded).is_ok(), "raising is allowed");
    }

    #[test]
    fn restarted_v12_writer_refuses_legacy_member_even_with_stale_local_state() {
        let mut local = node(Default::default());
        local.roles = elasticsearch_cluster::state::Role::defaults();
        let mut old = local.clone();
        old.id = "old".into();
        let mut state = ClusterState::empty("c");
        state.nodes.insert(old.id.clone(), old);
        state.nodes.insert(local.id.clone(), local.clone());
        advertise(&mut local.attributes);
        local.attributes.insert(SEGMENT_WRITE.into(), "12".into());
        assert!(require_local_writer(&state, &local).is_err());
        local.attributes.insert(SEGMENT_WRITE.into(), "11".into());
        assert!(require_local_writer(&state, &local).is_ok());
        let old = state.nodes.get_mut("old").unwrap();
        advertise(&mut old.attributes);
        local.attributes.insert(SEGMENT_WRITE.into(), "12".into());
        assert!(require_local_writer(&state, &local).is_err(), "advertised attrs alone are not live writer proof");
        state.nodes.remove("old");
        assert!(require_local_writer(&state, &local).is_ok());
    }

}
